const now = new Date().toISOString();
const body = $json.body || $json;
return [{ json: {
  ok: true,
  kind: 'night_report_logger',
  receivedAt: now,
  source: 'jarvis',
  report: {
    title: body.title || 'Jarvis Night Report',
    status: body.status || 'received',
    summary: body.summary || body.message || 'No summary provided',
    applies: body.applies || 0,
    failed: body.failed || 0
  },
  original: body
} }];
